-- findById 와 getReferenceById

@Test
void 두_조회() {
    em.clear();
    System.out.println("--- findById ---");
    Member a = memberRepository.findById(1L).orElseThrow();
    System.out.println("클래스: " + a.getClass().getSimpleName());

    em.clear();
    System.out.println("--- getReferenceById ---");
    Member b = memberRepository.getReferenceById(1L);
    System.out.println("클래스: " + b.getClass().getSimpleName());
    System.out.println("id 만 읽기: " + b.getId());
    System.out.println("--- 이제 필드를 읽는다 ---");
    System.out.println("이름: " + b.getUsername());
}

